#!/bin/sh
# Tinty hook: generate mako colours from base24 palette

hex() {
  eval "printf '#%s%s%s' \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_R\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_G\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_B\""
}

OUT="$HOME/.config/mako/tinted.conf"
mkdir -p "$(dirname "$OUT")"

cat > "$OUT" << CONF
# Auto-generated by tinty — do not edit
background-color=$(hex 00)f0
text-color=$(hex 05)
border-color=$(hex 03)73
progress-color=over $(hex 0D)

[urgency=low]
text-color=$(hex 04)
default-timeout=5000

[urgency=critical]
border-color=$(hex 08)
default-timeout=0
CONF

command -v makoctl >/dev/null && makoctl reload >/dev/null 2>&1
exit 0
